import java.util.*;

public class Main {
    public int minStartValueBrute(int[] nums) {
        int candidate = 1;
        while (true) {
            int running = candidate;
            boolean ok = true;
            for (int x : nums) {
                running += x;
                if (running < 1) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return candidate;
            }
            candidate++;
        }
    }

    public static void main(String[] args) {
        int[] nums = {-3, 2, -3, 4, 2};
        Main solution = new Main();
        int result = solution.minStartValueBrute(nums);
        System.out.println(result);
    }
}

