import java.util.*;

public class Main {
    public int minStartValue(int[] nums) {
        int runningSum = 0;
        int minPrefix = 0;
        for (int x : nums) {
            runningSum += x;
            minPrefix = Math.min(minPrefix, runningSum);
        }
        return 1 - minPrefix;
    }

    public static void main(String[] args) {
        int[] nums = {-3, 2, -3, 4, 2};
        Main solution = new Main();
        int result = solution.minStartValue(nums);
        System.out.println(result);
    }
}

